import AppKit

/// The Clip tab's AUDIO sections (spec §4.3): volume with its dB read-out,
/// Normalize and mute, the two fades, ducking, voice isolation
/// (`AudioPane+Isolation.swift`), the channel pick, the EQ and the hum notch
/// (`AudioPane+HumChannels.swift`, `AudioPane+EQ.swift`), noise reduction,
/// the compressor, pan, mix-to-mono, Detach Audio and Attach Audio, and the
/// limiter (`AudioPane+Limiter.swift`).
///
/// **This pane is never shown**: since the six tabs became three it is a
/// factory `ClipPane` holds and calls, last in the Clip tab, whenever at least
/// one selected clip carries audio (`InspectorTab.hasAudio`).
///
/// Everything here is one `set_audio` patch over the selection, except Detach
/// Audio, which is a clip-level op the editor already owns (⌥⌘D) — the pane
/// hands it back through `onCommand` rather than re-implementing it — and
/// Normalize, which is a `set_audio` PER CLIP because each clip gets its own
/// measured gain (`normalize()` says why it cannot go through
/// `InspectorBinding.ops(audio:)`).
///
/// The sections after Ducking are in SIGNAL ORDER rather than in order of
/// familiarity: Voice Isolation, Channels, EQ, Hum, noise reduction, the
/// compressor, the pan in Mix, then the Limiter, is the order the tap and
/// `AudioDSPChain` actually run them in, and the order matters to
/// what the numbers mean (the compressor's threshold is read against a signal
/// the reducer has already cleaned). Volume, the fades and ducking come first
/// in the pane and LAST in the signal, being the fader the core folds into the
/// plan's envelope. `ClipPane` keeps them in that order.
final class AudioPane: InspectorPaneView {
    /// The Volume section's loudness readout (spec §11 AU-15), dropped by a
    /// `loudness` cache post.
    let loudnessMemo = ClipLoudness.Memo()
    /// Voice Isolation's Status read-out (AU-56), dropped by an offline
    /// audio settlement.
    let isolationMemo = IsolationCache.Memo()
    /// Voice Effect's Status read-out (AU-146), dropped with it.
    let voiceMemo = IsolationCache.Memo(compute: VoiceCache.status(of:in:))

    override init(inspector: InspectorViewController) {
        super.init(inspector: inspector)
        NotificationCenter.default.addObserver(
            self, selector: #selector(loudnessCacheChanged(_:)), name: .mediaCacheDidChange,
            object: nil)
        // An isolation render landed or failed (AU-56): Voice Isolation's
        // status reads again.
        NotificationCenter.default.addObserver(
            self, selector: #selector(offlineAudioSettled(_:)), name: .reversedMediaDidChange,
            object: nil)
    }

    @objc private func offlineAudioSettled(_ note: Notification) {
        isolationMemo.invalidate()
        voiceMemo.invalidate()
        inspector?.refresh(isLive: false)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AudioPane does not support NSCoder")
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    /// A loudness file landed or was withdrawn: the memo's files and answers
    /// go, and the readout reads again.
    @objc private func loudnessCacheChanged(_ note: Notification) {
        guard note.userInfo?[MediaImporter.cacheKindKey] as? String == MediaImporter.loudnessKind
        else { return }
        loudnessMemo.invalidate()
        inspector?.refresh(isLive: false)
    }

    // MARK: Volume

    func volumeSection() -> InspectorSection {
        let binding = self.binding
        // The button lives in Volume rather than in a section of its own: it
        // writes the clip's volume and nothing else, and `ClipPane.makeSections`
        // would need editing for a seventh section — which is the omission
        // nothing type-checks and which has now bitten two phases in a row.
        // With an action selected the boxed "clip" tag follows it
        // (`InspectorClipTag`, #102): it writes the clip whatever is selected.
        let normalize = OptionButtonControl(
            title: "Normalize",
            action: { [weak self] in self?.normalize() },
            enabled: { !AudioPane.normalizable(binding).isEmpty }, onEdit: {})
        // The tooltip follows the chosen mode (`normalizeTip`, AU-15).
        let modeRow = normalizeRow(updating: normalize)
        return InspectorSection(
            id: "audio.volume", title: "Volume",
            summary: {
                let props = binding.audioProps
                if props.muted { return "muted" }
                guard props.decibels.isFinite else { return "silent" }
                return String(format: "%+.1f dB", props.decibels)
            },
            reset: { binding.apply("Volume", audio: AudioPatch(volume: 1, muted: false)) },
            defaultExpanded: false,
            rows: [
                // The field reaches the model's ceiling and the slider stops at
                // 400 %, where a linear rail is still useful (spec §11 AU-1).
                inspectorValueRow(
                    "Volume", binding, name: "Volume", unit: "%", decimals: 0, min: 0,
                    max: AudioNormalize.maxGain * 100, sliderMax: 400,
                    quick: [0, 50, 100, 150, 200, 400],
                    read: { binding.audioProps.volume * 100 },
                    ops: { binding.ops(audio: AudioPatch(volume: $0 / 100)) },
                    mixed: { binding.mixedAudio { $0.volume } }),
                inspectorRow(
                    "Gain",
                    [
                        inspectorReadout {
                            let decibels = binding.audioProps.decibels
                            guard decibels.isFinite else { return "silent" }
                            return String(format: "%+.1f dB", decibels)
                        }
                    ], binding: binding,
                    follows: binding.ops(audio: AudioPatch(volume: binding.audioProps.volume))),
            ] + loudnessRows() + [
                inspectorCheckRow(
                    "Mute", binding, name: "Mute",
                    read: { binding.audioProps.muted },
                    ops: { binding.ops(audio: AudioPatch(muted: $0)) },
                    mixed: { binding.mixedAudio { $0.muted } }),
                modeRow,
                inspectorButtonRow([normalize, InspectorClipTag(binding: binding)]),
                inspectorButtonRow([enhanceButton()]),
            ])
    }

    /// Normalize Clip's UI half: measure, then commit as ONE undo step, in
    /// the mode the Normalize row chose (`NormalizeChoice`, spec §11 AU-15).
    ///
    /// All of the arithmetic is `AudioNormalize`'s, which is the point — the
    /// agent's `normalize_clip` calls the same two functions, so the button and
    /// the tool cannot drift apart, and the gains are testable with no window
    /// open.
    ///
    /// It does NOT go through `binding.ops(audio:)`, and that is deliberate.
    /// `InspectorBinding.split` does two things every other control here wants
    /// and this one must not inherit: it folds every clip outside an action
    /// into ONE `set_audio` with many ids and one shared patch — but each clip
    /// gets its own measured gain — and it re-routes a clip the playhead is
    /// inside an action of into `set_action_end`, where Normalize means the
    /// clip's BASE level and never an action's end state. So the ops are built
    /// per clip, the shape `SpeedSheetController` already uses for a per-clip
    /// computed result.
    ///
    /// The scope is `normalizable` rather than the raw selection, so a shape,
    /// a silent movie or a nest picked alongside is simply not asked about
    /// instead of coming back as a refusal the user did not cause.
    ///
    /// **A run that can normalise nothing beeps**, and so does a second press
    /// on an already-normalised selection: `apply` refuses an empty op list,
    /// and `ProjectDocument.applyEdit` refuses an identity edit — the recorded
    /// consequence `SpeedSheetController` carries for the same reason. The
    /// button is not the place that explains WHY a clip was skipped; the tool
    /// reports each reason by name under `skipped`.
    /// The selected clips Normalize is offered for, which is `audioClips`
    /// minus the ones `AudioNormalize` could only refuse.
    ///
    /// It is not `audioClips` because a NEST is in that list and must not be
    /// in this one: a nest clip carrying anything audible has audio properties
    /// of its own, so every other control in this section is right to be live
    /// on it, but the plan flattens a nest and the clip has no segment — so
    /// Normalize on a nest can only beep. `AudioNormalize.canOffer` is the one
    /// home of that rule; the Clip menu's validator asks it the same question,
    /// or the two would disagree about the same selection.
    static func normalizable(_ binding: InspectorBinding) -> [ClipSnapshot] {
        binding.audioClips.filter { AudioNormalize.canOffer($0, in: binding.snapshot) }
    }

    private func normalize() {
        guard let document = binding.document else { return NSSound.beep() }
        AudioMeasureDoor.press(
            .normalize, document: document,
            clips: AudioPane.normalizable(binding).map { $0.id }, window: window)
    }

    // MARK: Fades

    /// An audio ramp's length in ticks, NOT snapped (core/CLAUDE.md Times,
    /// §11 #355); a negative as 0.
    private static func rampTicks(seconds: Double) -> Ticks {
        ReelTime.ticks(seconds: max(seconds, 0))
    }

    /// Fades are also the corner handles on the clip (§4.4), so the numbers
    /// here and the drag there write the same two fields. The rows store the
    /// length typed, off the frame grid (`rampTicks`); the handle's drag
    /// snaps it to whole frames (§11 #355). The two shape popups (format 29,
    /// spec §11 AU-114) are base-only, as the duck is (CI-3, AU-88).
    func fadeSection() -> InspectorSection {
        let binding = self.binding
        let shapes = FadeShape.allCases
        func shape(_ index: Int) -> FadeShape { shapes[min(max(index, 0), shapes.count - 1)] }
        return InspectorSection(
            id: "audio.fades", title: "Fades",
            summary: {
                let props = binding.audioProps
                guard props.fadeIn > 0 || props.fadeOut > 0 else { return "none" }
                return String(
                    format: "%.2f · %.2f s", ReelTime.seconds(props.fadeIn),
                    ReelTime.seconds(props.fadeOut))
            },
            reset: { binding.apply("Fades", audio: AudioPatch(fadeIn: 0, fadeOut: 0)) },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Fade in", binding, name: "Fade In", unit: " s", decimals: 2, min: 0, max: 10,
                    quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(binding.audioProps.fadeIn) },
                    ops: { binding.ops(audio: AudioPatch(fadeIn: Self.rampTicks(seconds: $0))) },
                    mixed: { binding.mixedAudio { $0.fadeIn } }),
                inspectorValueRow(
                    "Fade out", binding, name: "Fade Out", unit: " s", decimals: 2, min: 0,
                    max: 10, quick: [0, 0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(binding.audioProps.fadeOut) },
                    ops: { binding.ops(audio: AudioPatch(fadeOut: Self.rampTicks(seconds: $0))) },
                    mixed: { binding.mixedAudio { $0.fadeOut } }),
                inspectorPopupRow(
                    "In shape", binding, name: "Fade In Shape", items: shapes.map { $0.title },
                    read: { shapes.firstIndex(of: binding.audioProps.fadeInShape) ?? 0 },
                    ops: { binding.ops(audio: AudioPatch(fadeInShape: shape($0))) },
                    mixed: { binding.mixedAudio { $0.fadeInShape } }),
                inspectorPopupRow(
                    "Out shape", binding, name: "Fade Out Shape", items: shapes.map { $0.title },
                    read: { shapes.firstIndex(of: binding.audioProps.fadeOutShape) ?? 0 },
                    ops: { binding.ops(audio: AudioPatch(fadeOutShape: shape($0))) },
                    mixed: { binding.mixedAudio { $0.fadeOutShape } }),
            ])
    }

    // MARK: Ducking

    /// "Lower other audio to N % while this clip plays" — by the clip's
    /// length, or (Duck by Speech, format 29, spec §11 AU-110..AU-113) only
    /// while its speech plays, widened by Pre-roll and Hold. The core folds
    /// either into the other clips' envelopes.
    ///
    /// Every control writes a whole `DuckProps`: the patch replaces the
    /// object, so each edit re-sends the other values as they stand.
    /// Attack, release, pre-roll and hold are stored as typed, off the frame
    /// grid (§11 #355).
    ///
    /// **Choosing Speech is ONE edit with the spans** (AU-111): the
    /// `set_media_speech` each media without spans needs, from its voice
    /// cache (`DuckSpeech.ops`), then the `set_audio`. Every other duck edit
    /// re-sends `mode`, so on a Speech duck it carries the same spans first,
    /// as `AgentServer.setAudio` does: a Level edit on a pasted spanless
    /// Speech duck saves its media's spans and applies. A media whose cache
    /// cannot be read adds none, and the core refuses the edit in its own
    /// sentence rather than the row doing nothing. Speech cannot be chosen
    /// — the popup is disabled while the duck follows the clip's length —
    /// for a selection with a clip that is not a media clip with sound, or
    /// whose speech has not been detected yet (`DuckSpeech.problem`).
    func duckSection() -> InspectorSection {
        let binding = self.binding
        func current() -> DuckProps { binding.audioProps.duck ?? DuckProps() }
        func ops(_ next: DuckProps) -> [ReelOp] {
            let set = binding.ops(audio: AudioPatch(duck: .some(next)))
            guard next.mode == .speech else { return set }
            let spans = (try? DuckSpeech.ops(
                for: binding.audioClips, in: binding.snapshot,
                cacheDirectory: binding.document?.cacheDirectory)) ?? []
            return spans + set
        }
        func on() -> Bool { binding.audioProps.duck != nil }
        func speech() -> Bool { on() && current().mode == .speech }
        func offerable() -> Bool {
            speech()
                || DuckSpeech.problem(
                    for: binding.audioClips, in: binding.snapshot,
                    cacheDirectory: binding.document?.cacheDirectory) == nil
        }
        let modes = DuckMode.allCases
        return InspectorSection(
            id: "audio.duck", title: "Ducking",
            summary: { on() ? String(format: "%.0f%%", current().level * 100) : "off" },
            reset: { binding.apply("Ducking", audio: AudioPatch(duck: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Duck other audio", binding, name: "Ducking",
                    read: on,
                    ops: { value in
                        binding.ops(
                            audio: AudioPatch(duck: value ? .some(DuckProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedAudio { $0.duck != nil } }),
                inspectorPopupRow(
                    "Duck by", binding, name: "Ducking", items: ["Clip Length", "Speech"],
                    read: { modes.firstIndex(of: current().mode) ?? 0 },
                    ops: { index in
                        var d = current()
                        d.mode = modes[min(max(index, 0), modes.count - 1)]
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.mode } },
                    enabled: { on() && offerable() }),
                inspectorValueRow(
                    "Level", binding, name: "Duck Level", unit: "%", decimals: 0, min: 0, max: 100,
                    quick: [0, 10, 20, 30, 50],
                    read: { current().level * 100 },
                    ops: { value in
                        var d = current()
                        d.level = value / 100
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.level } },
                    enabled: on),
                inspectorValueRow(
                    "Attack", binding, name: "Duck Attack", unit: " s", decimals: 2, min: 0,
                    max: 5, quick: [0.1, 0.25, 0.5, 1],
                    read: { ReelTime.seconds(current().attack) },
                    ops: { value in
                        var d = current()
                        d.attack = Self.rampTicks(seconds: value)
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.attack } },
                    enabled: on),
                inspectorValueRow(
                    "Release", binding, name: "Duck Release", unit: " s", decimals: 2, min: 0,
                    max: 5, quick: [0.25, 0.5, 1, 2],
                    read: { ReelTime.seconds(current().release) },
                    ops: { value in
                        var d = current()
                        d.release = Self.rampTicks(seconds: value)
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.release } },
                    enabled: on),
                inspectorValueRow(
                    "Pre-roll", binding, name: "Duck Pre-roll", unit: " s", decimals: 2, min: 0,
                    max: 5, quick: [0, 0.25, 0.5, 1],
                    read: { ReelTime.seconds(current().preRoll) },
                    ops: { value in
                        var d = current()
                        d.preRoll = Self.rampTicks(seconds: value)
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.preRoll } },
                    enabled: speech),
                inspectorValueRow(
                    "Hold", binding, name: "Duck Hold", unit: " s", decimals: 2, min: 0,
                    max: 5, quick: [0, 0.25, 0.5, 1],
                    read: { ReelTime.seconds(current().hold) },
                    ops: { value in
                        var d = current()
                        d.hold = Self.rampTicks(seconds: value)
                        return ops(d)
                    },
                    mixed: { binding.mixedAudio { $0.duck?.hold } },
                    enabled: speech),
            ])
    }

    // MARK: Noise reduction

    /// "Remove noise", the Noise Reduction section's row (spec §4.3b's M3 line).
    ///
    /// The read-out states the strongest attenuation any part of the spectrum
    /// can receive, which is the one number that describes this honestly: the
    /// filter is a spectral attenuator over a noise floor it measures from the
    /// clip itself, so it never removes MORE than the floor it found, and the
    /// amount sets how far a bin may be pushed down. It is not a gate and does
    /// not silence anything between words; see
    /// `AudioNoiseReductionStage` for what it does, sample by sample.
    func noiseSection() -> InspectorSection {
        let binding = self.binding
        return InspectorSection(
            id: "audio.noise", title: "Noise Reduction",
            summary: {
                let amount = binding.audioProps.noiseReduction
                return amount <= 0 ? "off" : String(format: "%.0f%%", amount * 100)
            },
            reset: { binding.apply("Noise Reduction", audio: AudioPatch(noiseReduction: 0)) },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Remove noise", binding, name: "Remove Background Noise", unit: "%",
                    decimals: 0, min: 0, max: 100, quick: [0, 25, 50, 75, 100],
                    read: { binding.audioProps.noiseReduction * 100 },
                    ops: { binding.ops(audio: AudioPatch(noiseReduction: $0 / 100)) },
                    mixed: { binding.mixedAudio { $0.noiseReduction } }),
                inspectorRow(
                    "Depth",
                    [
                        inspectorReadout {
                            let amount = binding.audioProps.noiseReduction
                            if amount <= 0 { return "off" }
                            if amount >= 1 { return "floor removed" }
                            return String(format: "%.0f dB at most", -20 * log10(1 - amount))
                        }
                    ]),
            ])
    }

    // MARK: Compressor

    /// "Smooth volume levels" (spec §4.2's M3 line): a downward compressor
    /// across the clip.
    ///
    /// Every control writes a whole `CompressorProps`, the way Ducking writes
    /// a whole `DuckProps` — the patch replaces the object, so each edit
    /// re-sends the other four values as they stand.
    ///
    /// The two times are in MILLISECONDS and are not snapped to the frame
    /// grid — nor are the fades' and the duck's, which are in seconds
    /// (`rampTicks`, §11 #355). A compressor's attack is 10 ms where a frame
    /// is 33; snapping it would round the default to nothing. The core
    /// agrees — `check_audio` asks only that they are positive.
    func compressorSection() -> InspectorSection {
        let binding = self.binding
        func current() -> CompressorProps { binding.audioProps.compressor ?? CompressorProps() }
        func ops(_ next: CompressorProps) -> [ReelOp] {
            binding.ops(audio: AudioPatch(compressor: .some(next)))
        }
        func on() -> Bool { binding.audioProps.compressor != nil }
        func ticks(_ milliseconds: Double) -> Ticks {
            Ticks((max(milliseconds, 0) / 1000 * Double(ReelTime.perSecond)).rounded())
        }
        func milliseconds(_ ticks: Ticks) -> Double {
            Double(ticks) / Double(ReelTime.perSecond) * 1000
        }
        return InspectorSection(
            id: "audio.compressor", title: "Compressor",
            summary: { on() ? String(format: "%.1f:1", current().ratio) : "off" },
            reset: { binding.apply("Compressor", audio: AudioPatch(compressor: .some(nil))) },
            defaultExpanded: false,
            rows: [
                inspectorCheckRow(
                    "Smooth volume levels", binding, name: "Compressor",
                    read: on,
                    ops: { value in
                        binding.ops(
                            audio: AudioPatch(
                                compressor: value ? .some(CompressorProps()) : .some(nil)))
                    },
                    mixed: { binding.mixedAudio { $0.compressor != nil } }),
                inspectorValueRow(
                    "Threshold", binding, name: "Compressor Threshold", unit: " dB", decimals: 1,
                    min: -60, max: 0, quick: [-30, -24, -18, -12, -6],
                    read: { current().thresholdDb },
                    ops: { value in
                        var c = current()
                        c.thresholdDb = value
                        return ops(c)
                    },
                    mixed: { binding.mixedAudio { $0.compressor?.thresholdDb } },
                    enabled: on),
                inspectorValueRow(
                    "Ratio", binding, name: "Compressor Ratio", unit: ":1", decimals: 1, min: 1,
                    max: 20, quick: [1.5, 2, 3, 4, 8, 20],
                    read: { current().ratio },
                    ops: { value in
                        var c = current()
                        c.ratio = value
                        return ops(c)
                    },
                    mixed: { binding.mixedAudio { $0.compressor?.ratio } },
                    enabled: on),
                inspectorValueRow(
                    "Attack", binding, name: "Compressor Attack", unit: " ms", decimals: 0, min: 0,
                    max: 200, quick: [1, 5, 10, 30, 100],
                    read: { milliseconds(current().attack) },
                    ops: { value in
                        var c = current()
                        c.attack = ticks(value)
                        return ops(c)
                    },
                    mixed: { binding.mixedAudio { $0.compressor?.attack } },
                    enabled: on),
                inspectorValueRow(
                    "Release", binding, name: "Compressor Release", unit: " ms", decimals: 0,
                    min: 10, max: 2000, quick: [50, 100, 200, 500, 1000],
                    read: { milliseconds(current().release) },
                    ops: { value in
                        var c = current()
                        c.release = ticks(value)
                        return ops(c)
                    },
                    mixed: { binding.mixedAudio { $0.compressor?.release } },
                    enabled: on),
                inspectorValueRow(
                    "Makeup", binding, name: "Compressor Makeup", unit: " dB", decimals: 1, min: 0,
                    max: 24, quick: [0, 3, 6, 12],
                    read: { current().makeupDb },
                    ops: { value in
                        var c = current()
                        c.makeupDb = value
                        return ops(c)
                    },
                    mixed: { binding.mixedAudio { $0.compressor?.makeupDb } },
                    enabled: on),
            ])
    }

    // MARK: Mix

    /// Pan lives here rather than in a section of its own because it is a
    /// placement control, next to the other one.
    ///
    /// It is a BALANCE on a stereo clip — one gain per channel, unity at the
    /// centre, constant power across the sweep (`AudioPanLaw`) — and it is
    /// inaudible on a clip whose source is mono, because the widening to
    /// stereo happens after the point where the pan is applied. The read-out
    /// says which side, so "0" is never ambiguous.
    func mixSection() -> InspectorSection {
        let binding = self.binding
        let detach = commandButton(
            "Detach Audio", #selector(EditorViewController.detachAudio(_:)),
            toolTip: "Move the audio to its own clip on the track below (⌥⌘D)")
        let attach = commandButton(
            "Attach Audio", #selector(EditorViewController.attachAudio(_:)),
            toolTip: "Merge a detached sound back into its picture (⇧⌥⌘D)")
        return InspectorSection(
            id: "audio.mix", title: "Mix",
            summary: {
                let pan = binding.audioProps.pan
                if abs(pan) < 0.005 { return binding.audioProps.mono ? "mono" : "centre" }
                return String(format: "%@ %.0f", pan < 0 ? "left" : "right", abs(pan) * 100)
            },
            reset: { binding.apply("Mix", audio: AudioPatch(mono: false, pan: 0)) },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Pan", binding, name: "Pan", unit: "", decimals: 0, min: -100, max: 100,
                    quick: [-100, -50, 0, 50, 100],
                    read: { binding.audioProps.pan * 100 },
                    ops: { binding.ops(audio: AudioPatch(pan: $0 / 100)) },
                    mixed: { binding.mixedAudio { $0.pan } }),
                inspectorRow(
                    "Position",
                    [
                        inspectorReadout {
                            let pan = binding.audioProps.pan
                            if abs(pan) < 0.005 { return "centre" }
                            return String(
                                format: "%@ %.0f", pan < 0 ? "left" : "right", abs(pan) * 100)
                        }
                    ]),
                inspectorCheckRow(
                    "Mix to mono", binding, name: "Mix to Mono",
                    read: { binding.audioProps.mono },
                    ops: { binding.ops(audio: AudioPatch(mono: $0)) },
                    mixed: { binding.mixedAudio { $0.mono } }),
                inspectorButtonRow([detach, attach]),
            ])
    }
}

import AppKit

/// The Volume section's loudness half (spec §11 AU-15): the Loudness and At
/// volume readouts and the Normalize row's mode and target. The readout reads
/// through the pane's `loudnessMemo` (`ClipLoudness.Memo`), so a live Volume
/// or Pan drag reads no file and decodes no plan per tick; At volume is the
/// held answer plus the current base volume, through `AudioLimiterModel` while
/// the clip's limiter is on (AU-26) — on a clip with a stage the cache leaves
/// out, the last processed R0 or "≈" the cache figure (AU-64 (g)). Mode and
/// target are app-wide (`NormalizeChoice`), never an edit, so neither writes
/// the document.
extension AudioPane {

    /// The one clip the readout is about: exactly one selected clip Normalize
    /// is offered for, else nothing ("—").
    private var readoutClip: UInt32? {
        let clips = AudioPane.normalizable(binding)
        return clips.count == 1 && binding.clips.count == 1 ? clips[0].id : nil
    }

    private func loudnessAnswer() -> ClipLoudness.Answer {
        guard let clip = readoutClip, let document = binding.document else { return .unavailable }
        return loudnessMemo.answer(for: clip, in: document)
    }

    /// "−41.7 LUFS · −18.5 dBTP", "measuring…" or "—"; `gain` in dB is added
    /// to both (At volume). With `limiter`, the loudness is the model's at that
    /// gain and the peak is held at the limiter's ceiling (AU-24, AU-26).
    private func loudnessText(gain: Double, limiter: LimiterProps? = nil) -> String {
        switch loudnessAnswer() {
        case .pending: return "measuring…"
        case .unavailable: return "—"
        case .reading(let reading):
            return levelText(
                lufs: reading.lufs, truePeak: reading.truePeak, steps: reading.steps,
                peaks: reading.stepPeaks, gain: gain, limiter: limiter)
        }
    }

    /// One reading's figures at `gain` dB, through `limiter` when there is one.
    private func levelText(
        lufs measured: Double?, truePeak: Double, steps: [Double], peaks: [Double], gain: Double,
        limiter: LimiterProps?
    ) -> String {
        guard gain.isFinite else { return "silent" }
        var peak = truePeak > 0 ? 20 * log10(truePeak) + gain : -.infinity
        var lufs = measured.map { $0 + gain }
        if let limiter, measured != nil {
            let ceiling = pow(10, limiter.ceilingDb / 20)
            peak = min(peak, limiter.ceilingDb)
            lufs = AudioLimiterModel.integrated(
                steps: steps, peaks: peaks, gain: pow(10, gain / 20), ceiling: ceiling,
                releaseSeconds: Double(limiter.release) / Double(ReelTime.perSecond))
        }
        let peakText = peak.isFinite ? String(format: "%.1f dBTP", peak) : "−∞ dBTP"
        guard let lufs else { return "— LUFS · " + minus(peakText) }
        return minus(String(format: "%.1f LUFS · ", lufs) + peakText)
    }

    /// At volume (spec §11 AU-64 (g)): on a clip whose chain has a stage the
    /// loudness cache leaves out, the last R0 measured for its plan and chain
    /// (`ProcessedLoudness.Memo`) at the current volume and limiter, else the
    /// cache figure marked approximate; any other clip, the cache figure.
    private func atVolumeText(_ audio: AudioProps) -> (text: String, approximate: Bool) {
        let cached = loudnessText(gain: audio.decibels, limiter: audio.limiter)
        guard ProcessedLoudness.needsRender(audio), let clip = readoutClip,
            let document = binding.document, case .reading = loudnessAnswer()
        else { return (cached, false) }
        guard let processed = ProcessedLoudness.Memo.shared.reading(for: clip, in: document) else {
            return ("≈ " + cached, true)
        }
        let text = levelText(
            lufs: StepLoudness.integrated(processed.steps), truePeak: processed.peaks.max() ?? 0,
            steps: processed.steps, peaks: processed.peaks, gain: audio.decibels,
            limiter: audio.limiter)
        return (text, false)
    }

    static let approximateTip =
        "≈ before the clip's processing; Normalize or Enhance Voice measures through it."

    private func minus(_ text: String) -> String {
        text.replacingOccurrences(of: "-", with: "−")
    }

    /// The Loudness row (the clip's material at volume 1, pre-fader) and the
    /// At volume row (the same with the base volume's gain, through the
    /// clip's limiter when it has one).
    func loudnessRows() -> [NSView] {
        let binding = self.binding
        weak var atVolume: OptionDisplayControl?
        let readout = inspectorReadout(width: 160) { [weak self] in
            guard let self else { return "—" }
            let answer = self.atVolumeText(binding.audioProps)
            atVolume?.toolTip = answer.approximate ? AudioPane.approximateTip : nil
            return answer.text
        }
        atVolume = readout
        return [
            inspectorRow(
                "Loudness", [inspectorReadout(width: 160) { [weak self] in
                    self?.loudnessText(gain: 0) ?? "—"
                }]),
            inspectorRow("At volume", [readout]),
        ]
    }

    /// The Normalize row: Mode (Peak | Loudness) and Target (LUFS, −50…−5,
    /// quick −14, −16, −23; live only in Loudness). A change re-titles
    /// `button`'s tooltip and refreshes the pane.
    func normalizeRow(updating button: OptionButtonControl) -> NSView {
        button.toolTip = AudioPane.normalizeTip()
        let modes = AudioNormalize.Mode.allCases
        let popup = OptionPopupControl(
            width: 96, items: ["Peak", "Loudness"],
            read: { modes.firstIndex(of: NormalizeChoice.mode) ?? 0 },
            write: { [weak self, weak button] index in
                NormalizeChoice.mode = modes[max(0, min(index, modes.count - 1))]
                button?.toolTip = AudioPane.normalizeTip()
                self?.inspector?.refresh(isLive: false)
            },
            enabled: { true }, onEdit: {})
        let range = AudioNormalize.targetLUFSRange
        let target = OptionFieldControl(
            width: InspectorMetrics.fieldWidth, unit: "LUFS", decimals: 1,
            min: range.lowerBound, max: range.upperBound,
            quick: AudioNormalize.targetLUFSQuickPicks,
            read: { NormalizeChoice.targetLUFS },
            write: { [weak self, weak button] value in
                NormalizeChoice.targetLUFS = min(max(value, range.lowerBound), range.upperBound)
                button?.toolTip = AudioPane.normalizeTip()
                self?.inspector?.refresh(isLive: false)
            },
            enabled: { NormalizeChoice.mode == .loudness }, onEdit: {})
        return inspectorRow("Normalize", [popup, target])
    }

    /// The button's tooltip in the chosen mode. Two of the sentences are the
    /// limits, and they are here because this is where somebody meets them:
    /// the tool's description says the same things (road map 2 phase 5c,
    /// D-C3). The nest clause is a limit turned around: a nest alone leaves
    /// the button disabled, but a nest picked BESIDE an ordinary clip leaves it
    /// enabled and the nest quietly not asked about.
    static func normalizeTip() -> String {
        let rest =
            ". It REPLACES the volume rather than adding to it, so pressing it twice "
            + "changes nothing; it writes the clip's base level even while the playhead "
            + "is inside an action; and it leaves Mute alone. A nest is skipped: its "
            + "level lives in the clips inside it, not in the nest."
        switch NormalizeChoice.mode {
        case .peak:
            let level = String(format: "%.0f dBFS", AudioNormalize.defaultPeakDB)
            return "Set each selected clip's volume so its loudest moment reaches "
                + level.replacingOccurrences(of: "-", with: "−") + rest
        case .loudness:
            let target = String(format: "%.1f LUFS", NormalizeChoice.targetLUFS)
            let ceiling = String(format: "%.0f dBTP", AudioNormalize.ceilingDBTP)
            return ("Set each selected clip's volume so its integrated loudness reaches " + target
                + ", turning the clip's limiter on at " + ceiling + " where its true peak would "
                + "pass it, and stopping short where the volume would pass "
                + AudioNormalize.maxGainName)
                .replacingOccurrences(of: "-", with: "−") + rest
        }
    }
}
import Foundation

/// A clip's integrated loudness and true peak, read off its media's loudness
/// cache (`MediaLoudness`, spec §11 AU-10) over the window that plays — the
/// Volume section's readout and Loudness mode's measurement.
///
/// **What it counts** (AU-11): the plan's audio segments of the clip, the
/// export's channel layout (a mono record's z doubled: the export plays mono
/// as dual mono, +3.01 LU), and on stereo media the clip's own base `mono`
/// fold then `pan` as one 2×2 matrix. Not noise reduction or the compressor,
/// not the volume, fades, ducks, mute or solo, not an enclosing nest's fold:
/// the material's loudness, pre-fader, as Normalize's peak is.
///
/// **The window** (AU-12): the played time in 10 ms steps, each mapped to
/// source ticks through `MediaPeaks.sourceTick` (speed, a ramp's map) and
/// `ReverseMirror` (reversed), pooled in played order across the segments so
/// the gating grid is anchored at the played start; 400 ms gating blocks at
/// a 100 ms hop, counted from the whole steps; −70 LUFS then −10 LU, once.
/// A speed other than ×1 or a ramp reads within about 0.5 LU (spike S4).
/// Each step also carries its source midpoint and its high band (AU-61,
/// AU-63), for Enhance Voice.
enum ClipLoudness {
    /// One gating block: under it there is no integrated loudness.
    static let minimumPlayedTicks: Ticks = 240_000

    /// A step, and a record: 10 ms, the peaks grid.
    static var stepTicks: Ticks { MediaPeaks.bucketTicks }

    /// What a stereo clip's own channel settings do to the two channels, as
    /// `out = M · in`: the channel pick (AU-35), then the base mono fold
    /// (both channels to their mean), then the pan (`AudioPanLaw.gains`),
    /// `AudioClipDSP`'s order. EQ and hum are not counted.
    struct ChannelMatrix: Equatable {
        let m00, m01, m10, m11: Double

        static let identity = ChannelMatrix(m00: 1, m01: 0, m10: 0, m11: 1)

        init(m00: Double, m01: Double, m10: Double, m11: Double) {
            self.m00 = m00
            self.m01 = m01
            self.m10 = m10
            self.m11 = m11
        }

        init(_ props: AudioProps?) {
            guard let props else {
                self = .identity
                return
            }
            let gains = AudioPanLaw.gains(props.pan)
            let left = Double(gains.left)
            let right = Double(gains.right)
            let mix = props.mono
                ? ChannelMatrix(m00: left / 2, m01: left / 2, m10: right / 2, m11: right / 2)
                : ChannelMatrix(m00: left, m01: 0, m10: 0, m11: right)
            // The channel pick first (AU-34, AU-35): pan · fold · pick.
            let pick: ChannelMatrix
            switch props.channels {
            case .both: pick = .identity
            case .left: pick = ChannelMatrix(m00: 1, m01: 0, m10: 1, m11: 0)
            case .right: pick = ChannelMatrix(m00: 0, m01: 1, m10: 0, m11: 1)
            case .swapped: pick = ChannelMatrix(m00: 0, m01: 1, m10: 1, m11: 0)
            }
            self.init(
                m00: mix.m00 * pick.m00 + mix.m01 * pick.m10,
                m01: mix.m00 * pick.m01 + mix.m01 * pick.m11,
                m10: mix.m10 * pick.m00 + mix.m11 * pick.m10,
                m11: mix.m10 * pick.m01 + mix.m11 * pick.m11)
        }
    }

    struct Reading: Equatable {
        /// LUFS; nil under 0.4 s played, or when every block is under −70.
        let lufs: Double?
        /// Linear, the max over the played window (outward).
        let truePeak: Double
        let playedTicks: Ticks
        /// The 10 ms steps' energies (Σ over the output channels of the mean
        /// square), in played order: what `integrated` gates, and what
        /// `AudioLimiterModel` runs over (spec §11 AU-24).
        let steps: [Double]
        /// Each step's true peak, linear: the max of the records its energy
        /// read, on the louder output channel.
        let stepPeaks: [Double]
        /// Each step's source midpoint in forward-file ticks (after speed, a
        /// ramp's map and reversal): where Enhance Voice asks whether a step
        /// is speech (spec §11 AU-61).
        let stepSources: [Ticks]
        /// Each step's high-band energy (the records' `h`, AU-63), read as
        /// `steps` reads z: the export's layout, through the same matrix.
        let stepHighs: [Double]
    }

    enum Answer: Equatable {
        case reading(Reading)
        /// The cache is not written yet.
        case pending
        /// Nothing to read: not one measurable clip.
        case unavailable
    }

    // MARK: - The reading

    static func reading(
        _ cache: MediaLoudness, segments: [PlanSegment], pivots: [Ticks?], matrix: ChannelMatrix
    ) -> Reading {
        let step = stepTicks
        var steps: [Double] = []
        var stepPeaks: [Double] = []
        var stepSources: [Ticks] = []
        var stepHighs: [Double] = []
        var peak = 0.0
        var played: Ticks = 0
        let ordered = segments.indices.sorted { segments[$0].start < segments[$1].start }
        for index in ordered {
            let segment = segments[index]
            let pivot = index < pivots.count ? pivots[index] : nil
            played += segment.duration
            if let range = MediaPeaks.window(
                of: segment, from: segment.start, to: segment.start + segment.duration,
                reversedPivot: pivot, bucketTicks: step, count: cache.count) {
                for record in range { peak = max(peak, truePeak(cache, record, matrix)) }
            }
            guard step > 0 else { continue }
            for k in 0..<(segment.duration / step) {
                let from = segment.start + k * step
                var a = MediaPeaks.sourceTick(segment, at: from)
                var b = MediaPeaks.sourceTick(segment, at: from + step)
                if let pivot {
                    a = ReverseMirror.mirrored(a, about: pivot)
                    b = ReverseMirror.mirrored(b, about: pivot)
                }
                let read = energy(cache, from: min(a, b), to: max(a, b), matrix)
                steps.append(read.energy)
                stepPeaks.append(read.peak)
                stepSources.append(min(a, b) + abs(b - a) / 2)
                stepHighs.append(read.high)
            }
        }
        return Reading(
            lufs: StepLoudness.integrated(steps), truePeak: peak, playedTicks: played,
            steps: steps, stepPeaks: stepPeaks, stepSources: stepSources, stepHighs: stepHighs)
    }

    /// One step's Σ over the output channels of the mean square: the mean of
    /// records `[⌊a/step + ½⌋, ⌊b/step + ½⌋)`, else the one record holding the
    /// midpoint. Outside the file reads as silence. Its peak is the largest
    /// true peak of the records it read; its high band the same mean of `h`.
    static func energy(
        _ cache: MediaLoudness, from a: Ticks, to b: Ticks, _ matrix: ChannelMatrix
    ) -> (energy: Double, peak: Double, high: Double) {
        let step = stepTicks
        let first = MediaPeaks.bucketIndex(a + step / 2, bucket: step)
        let end = MediaPeaks.bucketIndex(b + step / 2, bucket: step)
        if end > first {
            let lower = max(0, first)
            let upper = min(cache.count, end)
            guard upper > lower else { return (0, 0, 0) }
            var sum = 0.0
            var peak = 0.0
            var high = 0.0
            for record in lower..<upper {
                sum += energy(cache, record, matrix)
                peak = max(peak, truePeak(cache, record, matrix))
                high += energy(cache, record, matrix, at: cache.highOffset)
            }
            return (sum / Double(end - first), peak, high / Double(end - first))
        }
        let middle = MediaPeaks.bucketIndex(a + (b - a) / 2, bucket: step)
        guard middle >= 0, middle < cache.count else { return (0, 0, 0) }
        return (
            energy(cache, middle, matrix), truePeak(cache, middle, matrix),
            energy(cache, middle, matrix, at: cache.highOffset)
        )
    }

    /// A record's Σ over the output channels of the mean square whose
    /// values start at `offset`: z at 0, h at `highOffset`.
    private static func energy(
        _ cache: MediaLoudness, _ record: Int, _ m: ChannelMatrix, at offset: Int = 0
    ) -> Double {
        let base = record * cache.width + offset
        let r = cache.records
        guard cache.channels == 2 else { return 2 * Double(r[base]) }  // dual mono
        let zL = Double(r[base]), zR = Double(r[base + 1]), zLR = Double(r[base + 2])
        let left = m.m00 * m.m00 * zL + m.m01 * m.m01 * zR + 2 * m.m00 * m.m01 * zLR
        let right = m.m10 * m.m10 * zL + m.m11 * m.m11 * zR + 2 * m.m10 * m.m11 * zLR
        return max(0, left) + max(0, right)
    }

    /// A record's true peak on the louder output channel, bounded by
    /// Σ|m|·tp where the matrix mixes the two.
    private static func truePeak(_ cache: MediaLoudness, _ record: Int, _ m: ChannelMatrix) -> Double {
        let base = record * cache.width
        let r = cache.records
        guard cache.channels == 2 else { return Double(r[base + 1]) }
        let tpL = Double(r[base + 3]), tpR = Double(r[base + 4])
        return max(abs(m.m00) * tpL + abs(m.m01) * tpR, abs(m.m10) * tpL + abs(m.m11) * tpR)
    }

    // MARK: - Loading

    static func loader(cacheDirectory: URL?) -> MediaCacheLoader<MediaLoudness> {
        MediaCacheLoader(cacheDirectory: cacheDirectory) {
            MediaImporter.loadLoudness(for: $0, in: $1)
        }
    }

    /// The answer for one clip of a document, from scratch: Normalize's
    /// admission, the clip's segments of one media, that media's cache.
    static func answer(
        for clip: UInt32, in document: ProjectDocument, loader: MediaCacheLoader<MediaLoudness>
    ) -> Answer {
        let project = document.editedProject
        guard let plan = project.plan else { return .unavailable }
        return answer(
            for: clip, snapshot: project.snapshot, segments: AudioNormalize.audioSegments(in: plan),
            loader: loader)
    }

    /// The same over a plan already indexed, so a run over many clips decodes
    /// the plan once.
    static func answer(
        for clip: UInt32, snapshot: ProjectSnapshot, segments: [UInt32: [PlanSegment]],
        loader: MediaCacheLoader<MediaLoudness>
    ) -> Answer {
        guard AudioNormalize.admit(clip, in: snapshot, segments: segments) == nil,
            let cited = segments[clip], let first = cited.first
        else { return .unavailable }
        let own = cited.filter { $0.media == first.media }
        guard let cache = loader.value(for: first.media) else { return .pending }
        return .reading(
            reading(
                cache, segments: own,
                pivots: own.map { MediaPeaks.reversedPivot(for: $0, in: snapshot) },
                matrix: ChannelMatrix(snapshot.clip(clip)?.audio)))
    }

    // MARK: - The readout's memo

    /// The Volume section's three holds (spec §11 AU-15): an answer per
    /// project handle and clip; one loader across handles, so each media's
    /// file is read once until `invalidate()` (a `loudness` post) drops it;
    /// and, while the document is live-editing, the held answer for the same
    /// clip of the same document without decoding the plan or walking the
    /// steps — a Volume or Pan drag reads nothing per tick, and the first
    /// non-live answer after the gesture recomputes. At volume is the pane's
    /// arithmetic on the answer and the current volume, never memoised.
    final class Memo {
        private weak var project: ReelProject?
        private weak var document: ProjectDocument?
        private var clip: UInt32?
        private var held: Answer?
        private var loader: MediaCacheLoader<MediaLoudness>?
        private var directory: URL?
        /// The files read and the answers computed since `init`: the probe's
        /// counts (C11).
        private(set) var reads = 0
        private(set) var computations = 0

        func answer(for clip: UInt32, in document: ProjectDocument) -> Answer {
            if let held, self.clip == clip, self.document === document,
                document.isLiveEditing || project === document.editedProject {
                return held
            }
            let directory = document.cacheDirectory
            if loader == nil || directory != self.directory {
                self.directory = directory
                loader = MediaCacheLoader(cacheDirectory: directory) { [weak self] media, url in
                    self?.reads += 1
                    return MediaImporter.loadLoudness(for: media, in: url)
                }
            }
            guard let loader else { return .unavailable }
            computations += 1
            let answer = ClipLoudness.answer(for: clip, in: document, loader: loader)
            self.project = document.editedProject
            self.document = document
            self.clip = clip
            held = answer
            return answer
        }

        func invalidate() {
            held = nil
            project = nil
            loader = nil
        }
    }
}
