    enum Command {
        case normalize, enhanceVoice, matchAudio

        var name: String {
            switch self {
            case .normalize: return "Normalize"
            case .enhanceVoice: return AudioEnhance.actionName
            case .matchAudio: return AudioMatch.actionName
            }
        }

